INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-002', N'MI-002', N'Reusable content', N'Build a library of approved, modular learning objects that can be reused across offerings to accelerate development and improve efficiency. Success means more than 1,000 objects are available, at least 20% are reused, and average non-degree development time is 28 days or less.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-003')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-003', N'MI-003', N'Data, EdTech & Infinity', N'Launch Infinity 2.0 and integrate data and education technology to support a connected, personalized learner journey. Success means the public launch is complete and three priority data domains are connected.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-004')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-004', N'MI-004', N'Team operating models', N'Design, document, approve, and test team operating models that align roles, workflows, and resources with strategic priorities. Success means every unit adopts a tested model that supports an adaptive and efficient organization.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-005')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-005', N'MI-005', N'Financial, Operational, and Initiative Dashboards', N'Create shared dashboards that give leaders and teams timely visibility into financial performance, operational health, and priority initiatives so decisions are based on consistent information. Success means key measures are reliable, easy to access, regularly updated, and actively used to identify risks, track progress, and direct resources.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-006')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-006', N'MI-006', N'Unified branding and messaging frameworks', N'Establish unified branding and messaging frameworks that present the college and its initiatives with a clear, consistent voice across audiences and channels. Success means 100% of external presence aligns with a college image/voice, teams use approved standards and reusable resources, communications reinforce strategic priorities, and stakeholders readily understand the college’s identity and value.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-007')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-007', N'MI-007', N'Centralized Process & Procedure workflows', N'Centralize core processes and procedures to make work easier to navigate, execute, and improve across the college. Success means cross-functional workflows have clear owners and documentation, reduce duplication and delays, and are routinely assessed, iterated on, and optimized using performance data.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-008')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-008', N'MI-008', N'Admin & Ops LLM Agent', N'Develop an Administration & Operations LLM agent that helps staff quickly find guidance, complete routine tasks, and make informed decisions using trusted internal information. Success means the agent provides accurate and useful responses, reduces time spent searching or handling repetitive work, and is adopted safely within established governance practices.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-009')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-009', N'MI-009', N'Build Organizational Learning Capability', N'Build the systems, habits, and leadership practices that enable the organization to learn continuously and translate insight into better ways of working. Success means staff share knowledge, develop relevant capabilities, test and apply improvements, and demonstrate stronger engagement and adaptability over time.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-010')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-010', N'MI-010', N'Optimized Org Structure & Resource Onboarding', N'Align the organizational structure, roles, resources, and onboarding experience across human and procurement needs with the college’s strategic priorities so people and partners can contribute effectively from the start. Success means accountabilities and handoffs are clear, compliant pathways are optimally leveraged, staffing and resources match priority work, and new team members reach productivity through a consistent, supportive onboarding process.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-011')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-011', N'MI-011', N'Growth Engine Readiness', N'Establish a scalable B2B growth engine supported by a clear strategy, a technology-enabled operating model, and repeatable sales and strategic account management processes.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-012')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-012', N'MI-012', N'Strategic Partnership & Revenue Growth', N'Build and convert a qualified B2B pipeline into sustained partnerships and revenue. Success means engaging more than 100 qualified leads, securing at least five new partners, launching at least two, and generating more than $1 million in annual recurring revenue.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
